package main
import("bytes";"encoding/json";"fmt";"io";"net/http";"os";"strings";"time";"github.com/golang-jwt/jwt/v5";"gorm.io/driver/sqlite";"gorm.io/gorm";"webbuilder/internal/database/models")
func main(){db,_:=gorm.Open(sqlite.Open("../../../data/webbuilder.db"),&gorm.Config{});var u models.User;db.First(&u);var p models.Project;db.Where("user_id = ?",u.ID).Order("id DESC").First(&p);sec,_:=os.ReadFile("../../../.jwt-secret");t:=jwt.NewWithClaims(jwt.SigningMethodHS256,jwt.MapClaims{"uid":u.ID,"exp":time.Now().Add(time.Hour).Unix()});tok,_:=t.SignedString([]byte(strings.TrimSpace(string(sec))));base:=fmt.Sprintf("http://127.0.0.1:18082/api/app-api/%d/auth",p.ID); call:=func(method,path string,body any,session string)string{b,_:=json.Marshal(body);req,_:=http.NewRequest(method,base+path,bytes.NewReader(b));req.Header.Set("Authorization","Bearer "+tok);req.Header.Set("Content-Type","application/json");if session!=""{req.Header.Set("X-Project-Session",session)};r,e:=http.DefaultClient.Do(req);if e!=nil{panic(e)};o,_:=io.ReadAll(r.Body);r.Body.Close();fmt.Printf("%s %s %d %s\n",method,path,r.StatusCode,o);var d map[string]any;json.Unmarshal(o,&d);if x,ok:=d["token"].(string);ok{return x};return ""};s:=call("POST","/register",map[string]any{"name":"Test User","email":fmt.Sprintf("auth-%d@example.com",time.Now().UnixNano()),"password":"password123"},"");call("GET","/me",nil,s);call("POST","/logout",nil,s);call("GET","/me",nil,s)}
